 async function cutin(form,text,dur,swapTo,swapAt){const F=FORMS[form],box=layer('sb-cutin');box.style.setProperty('--c1',F.c[0]);box.style.setProperty('--d',dur+'ms');
  const shade=el('div','sb-shade'),stands=el('div','sb-stands'),s1=stand(standSrc(form)),name=el('div','sb-skill');name.textContent=text;stands.append(s1);box.append(shade,stands,name);
  let s2=null;if(swapTo){s2=stand(standSrc(swapTo));s2.classList.add('sb-st2');stands.append(s2);setTimeout(()=>{s1.classList.add('sb-hide');s2.classList.add('sb-show');},swapAt);}
  void box.offsetWidth;box.classList.add('on');await sleep(dur);box.remove();}
 function stand(s){const im=el('img','sb-stand'+(s.mask?' sb-mask':''));im.alt='';im.draggable=false;if(globalThis.GameAssets)GameAssets.image(im,s.src);else im.src=s.src;return im;}
 function word(frame,text){const r=(frame.isConnected?frame:document.body).getBoundingClientRect(),w=layer('sb-word');w.textContent=text;Object.assign(w.style,{left:(r.left+r.width*.4)+'px',top:(r.top+r.height*.46)+'px',fontSize:Math.max(110,Math.min(460,r.width*.5))+'px'});void w.offsetWidth;w.classList.add('on');setTimeout(()=>w.remove(),1400);}
 function current(frame){return frame.isConnected?frame:document.querySelector('#combatMonsterArea .side-frame')||frame;}
 async function ultimate(frame,form,target,burst=false){if(holding||(frame._ult&&!burst))return;if(!burst)frame._ult=true;holding=true;frame._keep=true;document.body.classList.add('sb-ult');
  // 終結の一撃は敵を斬り捨てる演出（セリア）、途中の追加攻撃は敵が残るので共通の大招演出
  try{if(!burst&&form==='celia'&&DATA.cursed.celia)await ultCelia(frame,target);else await ultGeneric(frame,form,target);}
  catch(e){console.warn(e);}finally{holding=false;document.body.classList.remove('sb-ult');frame._keep=false;const a=frame.querySelector('.sb-actor');if(a){a._busy=false;a._cursed=false;a.classList.remove('sb-awaken','sb-mirror');a.style.left=a._left||'';a.style.visibility='';pose(a,'');}}}
 async function ultGeneric(frame,form,target){const F=FORMS[form],actor=frame.querySelector('.sb-actor');actor._busy=true;
  await cutin(form,F.skill,1500);frame=current(frame);const f=fx(frame);if(!f)return;fit(f,frame);pose(actor,'attack');knock(actor,true,-1);
  const a=box(frame,actor,.42),b=target&&box(frame,target,.55);if(a&&b){a.x-=a.w*.3;const bb=boost({...b},f),us=sheet('ult',form)||sheet('hit',form);const lead=us?playSheet(f,us,bb.x,bb.y,Math.min(f.W,f.H*1.6)*.95,1000):FX[F.fx](f,a,bb,F.c,true,frame,F)||0;await sleep(Math.min(lead,260));impact(f,bb,F.c,true);quake(frame);if(target){pose(target,'damage');knock(target,true,-1);}showCombo(frame,1);}
  await sleep(700);pose(actor,'');}
 function quake(frame){const m=frame.closest('.exp-stage-media')||frame;if(!m.animate)return;m.animate([{translate:'0 0'},{translate:'6px -3px'},{translate:'-5px 3px'},{translate:'3px 1px'},{translate:'0 0'}],{duration:300,easing:'ease-out'});}
 // セリア：妖刀覚醒 → 消灯 → 窓ごと一刀 → 背後に立つ → 灯りが戻り「斬」（用户 2026-11-28）。
 async function ultCelia(frame,target){const actor=frame.querySelector('.sb-actor');actor._busy=true;pose(actor,'');actor.classList.add('sb-awaken');
  const red=layer('sb-red');void red.offsetWidth;red.classList.add('on');
  setTimeout(()=>{actor.classList.add('sb-morph');actor._cursed=true;pose(actor,'');setTimeout(()=>actor.classList.remove('sb-morph'),400);},650);setTimeout(()=>{if(actor._cursed)pose(actor,'attack');},1050);
  const f=fx(frame);let aura=null;if(f){fit(f,frame);aura=setInterval(()=>{const r=box(frame,actor,.5);if(!r)return;for(let i=0;i<3;i++){const x0=r.x+r.w*rnd(-.35,.35),y0=r.top+r.h*rnd(.55,.98),sw=rnd(0,6),col=Math.random()<.5?'#c4122f':'#2a0610';
   add(f,rnd(700,1000),(k,cx)=>{cx.globalAlpha=(k<.2?k/.2:1-(k-.2)/.8)*.9;const x=x0+Math.sin(sw+k*6)*8,y=y0-k*r.h*.8,s=(1-k)*9+2;cx.fillStyle=col;glow(cx,'#ff1e3c',6);cx.beginPath();cx.moveTo(x,y-s*2.2);cx.quadraticCurveTo(x+s,y,x,y+s);cx.quadraticCurveTo(x-s,y,x,y-s*2.2);cx.fill();});}},60);}
  await cutin('celia','妖刀・覚醒',2600,'celia_cursed',1100);clearInterval(aura);await sleep(200);
  // 消灯
  const dark=layer('sb-black');void dark.offsetWidth;red.remove();dark.classList.add('on');await sleep(450);frame=current(frame);
  // 窓ごと一刀：右上から左下へ、ゲーム画面全体を横切る一本の線
  const W=innerWidth,H=innerHeight,L={x0:W*1.02,y0:H*.12,x1:-W*.02,y1:H*.82},ns='http://www.w3.org/2000/svg';
  const line=layer('sb-cutline'),svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 '+W+' '+H);svg.setAttribute('width',W);svg.setAttribute('height',H);
  for(const c of ['sb-l1','sb-l2']){const l=document.createElementNS(ns,'line');l.setAttribute('class',c);l.setAttribute('x1',L.x0);l.setAttribute('y1',L.y0);l.setAttribute('x2',L.x1);l.setAttribute('y2',L.y1);svg.append(l);}line.append(svg);await sleep(330);
  // 窓が斜めに割れてずれる：見えている画面を二枚に複製し、線で切り分けて逆向きにずらす
  const root=document.getElementById('appFrame')||document.getElementById('gameRoot')||document.body,rr=root.getBoundingClientRect(),yAt=x=>L.y0+(L.y1-L.y0)*(x-L.x0)/(L.x1-L.x0);
  const yl=(yAt(rr.left)-rr.top)/rr.height*100,yr=(yAt(rr.right)-rr.top)/rr.height*100,split=layer('sb-split');
  const halves=['polygon(0 0,100% 0,100% '+yr+'%,0 '+yl+'%)','polygon(0 '+yl+'%,100% '+yr+'%,100% 100%,0 100%)'].map(cp=>{const c=root.cloneNode(true),w=el('div','sb-half');// id は残す（#appFrame/#gameRoot 前提のスタイルを保つ）。複製は body の末尾なので getElementById は本物を返す。
   // 窓枠は zoom で縮小されているので、位置と切り口は外側の箱に持たせ、中の複製はそのまま置く
   c.querySelectorAll('.sb-ghost,.damage-float,.damage-burst,.loot-drop,.sb-combo').forEach(n=>n.remove());c.style.margin='0';
   Object.assign(w.style,{left:rr.left+'px',top:rr.top+'px',width:rr.width+'px',height:rr.height+'px',clipPath:cp});w.append(c);split.append(w);
   const gr=document.getElementById('gameRoot'),cg=c.id==='gameRoot'?c:c.querySelector('#gameRoot');if(gr&&cg&&cg!==gr)cg.scrollTop=gr.scrollTop;return w;});
  root.style.visibility='hidden';line.classList.add('gap');const len=Math.hypot(W,H*.7),ux=(L.x1-L.x0)/len,uy=(L.y1-L.y0)/len,D=42;
  halves.forEach((c,i)=>{const s=i?1:-1;c.animate([{transform:'none'},{transform:'translate('+(s*-uy*10+s*ux*D*-1)+'px,'+(s*ux*10*-1*-1+s*uy*D*-1)+'px) rotate('+(s*-.6)+'deg)'}],{duration:220,easing:'cubic-bezier(.2,.9,.3,1)',fill:'forwards'});});
  await sleep(900);halves.forEach(c=>c.animate([{},{transform:'none'}],{duration:260,easing:'ease-in',fill:'forwards'}));await sleep(270);root.style.visibility='';split.remove();line.classList.add('fade');setTimeout(()=>line.remove(),500);
  // 背後に立つ
  frame=current(frame);const act=frame.querySelector('.sb-actor')||actor,tu=target&&frame.contains(target)?target:frame.querySelector('.sb-foe');act.classList.remove('sb-awaken');act._cursed=true;pose(act,'');
  if(tu){act.style.left=Math.max(6,parseFloat(tu.style.left)-14)+'%';}await sleep(250);
  // 灯りが戻る → 「斬」 → 敵も同じ線で二つにずれる
  dark.classList.remove('on');setTimeout(()=>dark.remove(),400);await sleep(380);word(frame,'斬');await sleep(300);quake(frame);
  const f2=fx(frame);if(tu){const ei=tu.querySelector('.sb-img'),er=ei.getBoundingClientRect(),sr=frame.getBoundingClientRect();if(er.width){const eh=[0,1].map(i=>{const c=el('img','sb-ehalf');c.src=ei.currentSrc||ei.src;c.alt='';Object.assign(c.style,{left:(er.left-sr.left)+'px',top:(er.top-sr.top)+'px',width:er.width+'px',height:er.height+'px',clipPath:i?'polygon(0 70%,100% 25%,100% 100%,0 100%)':'polygon(0 0,100% 0,100% 25%,0 70%)'});frame.append(c);return c;});
   tu.classList.add('sb-split');eh.forEach((c,i)=>{c.animate([{translate:'0 0',opacity:1},{translate:i?'8px 6px':'-10px -8px',opacity:1,offset:.3},{translate:i?'14px 20px':'-16px -4px',opacity:0}],{duration:900,fill:'forwards',easing:'ease-out'});});setTimeout(()=>eh.forEach(c=>c.remove()),950);
   if(f2){fit(f2,frame);const b=boost(box(frame,tu,.55)||{x:er.left-sr.left+er.width/2,y:er.top-sr.top+er.height/2,w:er.width,h:er.height,top:0,bottom:0},f2);petals(f2,b,26,['#ffc2d2','#c4122f']);}}}
  await sleep(1000);act.style.left=act._left||'';}
 // ---------- 样式表 ----------
